/* ═══════════════════════════════════════════════════════
   NAE Guanhães · gerador de QR Code
   ───────────────────────────────────────────────────────
   Modo byte, correção de erro nível H, sem depender de
   nada de fora. Desenha o QR do endereço do site dentro de
   todo elemento com [data-qr], e deixa o resultado em
   window.NAE_QR para quem quiser reaproveitar.

   Usado por: cartaz.html (parede) e guia.html (bolso).
   ═══════════════════════════════════════════════════════ */
/* ═══════════════════════════════════════════════════════
   Gerador de QR Code (modo byte, correção de erro nível H)
   Escrito para este cartaz, sem dependências externas.
   ═══════════════════════════════════════════════════════ */
(function () {
  'use strict';

  var URL_SITE = 'https://naeguanhaes.github.io/';

  /* Marca oficial do NAE embutida em base64: um SVG carregado como <img>
     nao busca arquivos externos, entao a imagem viaja dentro do SVG. */
  var MARCA_NAE = 'data:image/png;base64,';

  /* ── Aritmética em GF(256) ────────────────────────── */
  var EXP = new Array(512), LOG = new Array(256);
  (function () {
    var x = 1;
    for (var i = 0; i < 255; i++) { EXP[i] = x; LOG[x] = i; x <<= 1; if (x & 0x100) x ^= 0x11D; }
    for (var j = 255; j < 512; j++) EXP[j] = EXP[j - 255];
  })();
  function mul(a, b) { return (a === 0 || b === 0) ? 0 : EXP[LOG[a] + LOG[b]]; }

  function polGerador(n) {
    var p = [1];
    for (var i = 0; i < n; i++) {
      var q = new Array(p.length + 1);
      for (var k = 0; k < q.length; k++) q[k] = 0;
      for (var j = 0; j < p.length; j++) {
        q[j] ^= p[j];
        q[j + 1] ^= mul(p[j], EXP[i]);
      }
      p = q;
    }
    return p;
  }

  function correcao(dados, n) {
    var g = polGerador(n);
    var r = dados.slice();
    for (var i = 0; i < n; i++) r.push(0);
    for (var d = 0; d < dados.length; d++) {
      var c = r[d];
      if (c !== 0) for (var j = 0; j < g.length; j++) r[d + j] ^= mul(g[j], c);
    }
    return r.slice(dados.length);
  }

  /* ── Tabelas (nível H, versões 1 a 6) ─────────────── */
  var CAPACIDADE = [7, 14, 24, 34, 44, 58];              // bytes em modo byte
  var BLOCOS = [                                          // [cw de correção por bloco, [[qtd, cw de dados], …]]
    [17, [[1, 9]]],
    [28, [[1, 16]]],
    [22, [[2, 13]]],
    [16, [[4, 9]]],
    [22, [[2, 11], [2, 12]]],
    [28, [[4, 15]]]
  ];
  var ALINHAMENTO = [[], [6, 18], [6, 22], [6, 26], [6, 30], [6, 34]];

  function gerar(texto) {
    var bytes = Array.prototype.slice.call(new TextEncoder().encode(texto));

    var versao = 0;
    for (var v = 0; v < CAPACIDADE.length; v++) {
      if (bytes.length <= CAPACIDADE[v]) { versao = v + 1; break; }
    }
    if (!versao) throw new Error('Texto longo demais para as versões suportadas.');

    var tam = 17 + 4 * versao;
    var info = BLOCOS[versao - 1];
    var cwCorrecao = info[0];
    var grupos = info[1];
    var totalDados = 0;
    grupos.forEach(function (g) { totalDados += g[0] * g[1]; });

    /* ── Fluxo de bits ── */
    var bits = [];
    function push(valor, n) { for (var i = n - 1; i >= 0; i--) bits.push((valor >>> i) & 1); }
    push(4, 4);                       // modo byte
    push(bytes.length, 8);            // contador (versões 1 a 9)
    bytes.forEach(function (b) { push(b, 8); });
    var capacidadeBits = totalDados * 8;
    for (var t = 0; t < 4 && bits.length < capacidadeBits; t++) bits.push(0);
    while (bits.length % 8 !== 0) bits.push(0);

    var cw = [];
    for (var i = 0; i < bits.length; i += 8) {
      var b = 0;
      for (var k = 0; k < 8; k++) b = (b << 1) | bits[i + k];
      cw.push(b);
    }
    var enchimento = [0xEC, 0x11], e = 0;
    while (cw.length < totalDados) { cw.push(enchimento[e % 2]); e++; }

    /* ── Blocos e intercalação ── */
    var blocosDados = [], blocosCorrecao = [], pos = 0;
    grupos.forEach(function (g) {
      for (var n = 0; n < g[0]; n++) {
        var d = cw.slice(pos, pos + g[1]);
        pos += g[1];
        blocosDados.push(d);
        blocosCorrecao.push(correcao(d, cwCorrecao));
      }
    });

    var finais = [];
    var maiorDados = Math.max.apply(null, blocosDados.map(function (b) { return b.length; }));
    for (var c = 0; c < maiorDados; c++) {
      for (var bl = 0; bl < blocosDados.length; bl++) {
        if (c < blocosDados[bl].length) finais.push(blocosDados[bl][c]);
      }
    }
    for (var cc = 0; cc < cwCorrecao; cc++) {
      for (var bc = 0; bc < blocosCorrecao.length; bc++) finais.push(blocosCorrecao[bc][cc]);
    }

    /* ── Matriz e padrões fixos ── */
    var m = [], fixo = [];
    for (var r = 0; r < tam; r++) {
      m.push(new Array(tam).fill(0));
      fixo.push(new Array(tam).fill(false));
    }
    function marcar(linha, coluna, escuro) {
      if (linha < 0 || coluna < 0 || linha >= tam || coluna >= tam) return;
      m[linha][coluna] = escuro ? 1 : 0;
      fixo[linha][coluna] = true;
    }

    function localizador(l0, c0) {
      for (var dl = -1; dl <= 7; dl++) {
        for (var dc = -1; dc <= 7; dc++) {
          var l = l0 + dl, c = c0 + dc;
          if (l < 0 || c < 0 || l >= tam || c >= tam) continue;
          var dist = Math.max(Math.abs(dl - 3), Math.abs(dc - 3));
          marcar(l, c, dist !== 2 && dist <= 3);
        }
      }
    }
    localizador(0, 0); localizador(0, tam - 7); localizador(tam - 7, 0);

    for (var i2 = 8; i2 < tam - 8; i2++) {
      marcar(6, i2, i2 % 2 === 0);
      marcar(i2, 6, i2 % 2 === 0);
    }

    var centros = ALINHAMENTO[versao - 1];
    centros.forEach(function (cl) {
      centros.forEach(function (cc2) {
        var perto = (cl === 6 && cc2 === 6) || (cl === 6 && cc2 === tam - 7) || (cl === tam - 7 && cc2 === 6);
        if (perto) return;
        for (var dl = -2; dl <= 2; dl++) {
          for (var dc = -2; dc <= 2; dc++) {
            var dist = Math.max(Math.abs(dl), Math.abs(dc));
            marcar(cl + dl, cc2 + dc, dist !== 1);
          }
        }
      });
    });

    /* reserva das áreas de formato */
    for (var f = 0; f <= 8; f++) { if (!fixo[8][f]) marcar(8, f, false); if (!fixo[f][8]) marcar(f, 8, false); }
    for (var f2 = 0; f2 < 8; f2++) { if (!fixo[8][tam - 1 - f2]) marcar(8, tam - 1 - f2, false); if (!fixo[tam - 1 - f2][8]) marcar(tam - 1 - f2, 8, false); }
    marcar(tam - 8, 8, true);

    /* ── Colocação dos dados ── */
    var idx = 0;
    for (var dir = tam - 1; dir >= 1; dir -= 2) {
      if (dir === 6) dir = 5;
      for (var vert = 0; vert < tam; vert++) {
        for (var lado = 0; lado < 2; lado++) {
          var col = dir - lado;
          var subindo = ((dir + 1) & 2) === 0;
          var lin = subindo ? tam - 1 - vert : vert;
          if (fixo[lin][col]) continue;
          var bit = 0;
          if (idx < finais.length * 8) bit = (finais[idx >>> 3] >>> (7 - (idx & 7))) & 1;
          m[lin][col] = bit;
          idx++;
        }
      }
    }

    /* ── Máscaras ── */
    function mascara(n, l, c) {
      switch (n) {
        case 0: return (l + c) % 2 === 0;
        case 1: return l % 2 === 0;
        case 2: return c % 3 === 0;
        case 3: return (l + c) % 3 === 0;
        case 4: return (Math.floor(l / 2) + Math.floor(c / 3)) % 2 === 0;
        case 5: return ((l * c) % 2) + ((l * c) % 3) === 0;
        case 6: return (((l * c) % 2) + ((l * c) % 3)) % 2 === 0;
        default: return (((l + c) % 2) + ((l * c) % 3)) % 2 === 0;
      }
    }

    function bitsFormato(n) {
      var dado = (2 << 3) | n;                 // 10 = nível H
      var resto = dado;
      for (var i3 = 0; i3 < 10; i3++) resto = (resto << 1) ^ ((resto >>> 9) * 0x537);
      return ((dado << 10) | resto) ^ 0x5412;
    }

    function aplicarFormato(mat, n) {
      var b = bitsFormato(n);
      function bit(i) { return (b >>> i) & 1; }
      for (var i4 = 0; i4 <= 5; i4++) mat[i4][8] = bit(i4);
      mat[7][8] = bit(6);
      mat[8][8] = bit(7);
      mat[8][7] = bit(8);
      for (var i5 = 9; i5 < 15; i5++) mat[8][14 - i5] = bit(i5);
      for (var i6 = 0; i6 < 8; i6++) mat[8][tam - 1 - i6] = bit(i6);
      for (var i7 = 8; i7 < 15; i7++) mat[tam - 15 + i7][8] = bit(i7);
      mat[tam - 8][8] = 1;
    }

    function penalidade(mat) {
      var p = 0, escuros = 0, i8, j8;

      function linhaOuColuna(pegar) {
        for (i8 = 0; i8 < tam; i8++) {
          var cor = -1, corrida = 0;
          var historico = [];
          for (j8 = 0; j8 < tam; j8++) {
            var v2 = pegar(i8, j8);
            if (v2 === cor) { corrida++; if (corrida === 5) p += 3; else if (corrida > 5) p += 1; }
            else { historico.push(corrida); cor = v2; corrida = 1; }
          }
          historico.push(corrida);
        }
      }
      linhaOuColuna(function (a, b2) { return mat[a][b2]; });
      linhaOuColuna(function (a, b2) { return mat[b2][a]; });

      for (i8 = 0; i8 < tam - 1; i8++) {
        for (j8 = 0; j8 < tam - 1; j8++) {
          var s = mat[i8][j8] + mat[i8][j8 + 1] + mat[i8 + 1][j8] + mat[i8 + 1][j8 + 1];
          if (s === 0 || s === 4) p += 3;
        }
      }

      var alvo = [1, 0, 1, 1, 1, 0, 1, 0, 0, 0, 0];
      function procurar(pegar) {
        for (i8 = 0; i8 < tam; i8++) {
          for (j8 = 0; j8 + 11 <= tam; j8++) {
            var ok = true, okInv = true;
            for (var k2 = 0; k2 < 11; k2++) {
              var v3 = pegar(i8, j8 + k2);
              if (v3 !== alvo[k2]) ok = false;
              if (v3 !== alvo[10 - k2]) okInv = false;
            }
            if (ok) p += 40;
            if (okInv) p += 40;
          }
        }
      }
      procurar(function (a, b2) { return mat[a][b2]; });
      procurar(function (a, b2) { return mat[b2][a]; });

      for (i8 = 0; i8 < tam; i8++) for (j8 = 0; j8 < tam; j8++) escuros += mat[i8][j8];
      var pct = (escuros * 100) / (tam * tam);
      p += Math.floor(Math.abs(pct - 50) / 5) * 10;
      return p;
    }

    var melhor = null, melhorNota = Infinity;
    for (var n2 = 0; n2 < 8; n2++) {
      var copia = m.map(function (linha) { return linha.slice(); });
      for (var l2 = 0; l2 < tam; l2++) {
        for (var c3 = 0; c3 < tam; c3++) {
          if (!fixo[l2][c3] && mascara(n2, l2, c3)) copia[l2][c3] ^= 1;
        }
      }
      aplicarFormato(copia, n2);
      var nota = penalidade(copia);
      if (nota < melhorNota) { melhorNota = nota; melhor = copia; }
    }

    return { matriz: melhor, tamanho: tam, versao: versao };
  }

  /* ── Desenho: módulos redondos + símbolo do NAE ───── */
  function desenhar(qr) {
    var n = qr.tamanho, m = qr.matriz;
    var borda = n * 0.275;                        // respiro até a borda do círculo
    var lado = n + borda * 2;
    var centro = lado / 2;
    var raioLogo = n * 0.142;                     // buraco central para o símbolo
    var escuro = '#2C516F';   /* azul da marca, escurecido para dar contraste de leitura */

    function ehLocalizador(l, c) {
      return (l < 7 && c < 7) || (l < 7 && c >= n - 7) || (l >= n - 7 && c < 7);
    }

    var pecas = [];
    pecas.push('<circle cx="' + centro + '" cy="' + centro + '" r="' + (lado / 2 - 0.4) + '" fill="#FFFFFF"/>');
    pecas.push('<circle cx="' + centro + '" cy="' + centro + '" r="' + (lado / 2 - 0.9) + '" fill="none" stroke="' + escuro + '" stroke-width="0.85"/>');
    pecas.push('<circle cx="' + centro + '" cy="' + centro + '" r="' + (lado / 2 - 2.2) + '" fill="none" stroke="#D91F35" stroke-width="0.5"/>');

    for (var l = 0; l < n; l++) {
      for (var c = 0; c < n; c++) {
        if (!m[l][c] || ehLocalizador(l, c)) continue;
        var cx = borda + c + 0.5, cy = borda + l + 0.5;
        var dx = cx - centro, dy = cy - centro;
        if (Math.sqrt(dx * dx + dy * dy) < raioLogo + 0.9) continue;
        /* módulo arredondado ocupando a célula inteira: fica redondo e continua
           legível, porque as linhas de tempo e os cantos não se fragmentam */
        pecas.push('<rect x="' + (borda + c) + '" y="' + (borda + l) + '" width="1" height="1" rx="0.4" fill="' + escuro + '"/>');
      }
    }

    [[0, 0], [0, n - 7], [n - 7, 0]].forEach(function (p) {
      var x = borda + p[1], y = borda + p[0];
      pecas.push('<rect x="' + (x + 0.5) + '" y="' + (y + 0.5) + '" width="6" height="6" rx="2.1" fill="none" stroke="' + escuro + '" stroke-width="1"/>');
      pecas.push('<rect x="' + (x + 2) + '" y="' + (y + 2) + '" width="3" height="3" rx="1.05" fill="' + escuro + '"/>');
    });

    /* marca oficial do NAE ao centro */
    var alturaMarca = raioLogo * 1.78;             // preenche o furo central
    var larguraMarca = alturaMarca * (170 / 271);  // proporção da marca oficial
    pecas.push('<circle cx="' + centro + '" cy="' + centro + '" r="' + (raioLogo + 0.55) + '" fill="#FFFFFF"/>');
    pecas.push(
      '<image href="' + MARCA_NAE + '"' +
      ' x="' + (centro - larguraMarca / 2).toFixed(2) + '"' +
      ' y="' + (centro - alturaMarca / 2).toFixed(2) + '"' +
      ' width="' + larguraMarca.toFixed(2) + '"' +
      ' height="' + alturaMarca.toFixed(2) + '"' +
      ' preserveAspectRatio="xMidYMid meet"/>'
    );

    return '<svg width="1400" height="1400" viewBox="0 0 ' + lado.toFixed(2) + ' ' + lado.toFixed(2) + '" ' +
           'xmlns="http://www.w3.org/2000/svg" ' +
           'role="img" aria-label="QR code do site do NAE Guanhães">' + pecas.join('') + '</svg>';
  }

  var qr = gerar(URL_SITE);
  var svg = desenhar(qr);
  document.querySelectorAll('[data-qr]').forEach(function (alvo) { alvo.innerHTML = svg; });

  window.NAE_QR = { url: URL_SITE, versao: qr.versao, tamanho: qr.tamanho, svg: svg, matriz: qr.matriz };
})();
